-- Reference data (generated): chronological watch order of films and series ('watch_order'),
-- more books (incl. the Fantastic Beasts screenplays), most watched and upcoming anime,
-- and a cover photo per universe (freely licensed Wikimedia Commons photos, credited).
-- Idempotent: existing rows and staff edits are kept.

-- New archive sections.
UPDATE public.universe_settings st SET features = (
    SELECT jsonb_agg(f ORDER BY ord) FROM (
      SELECT f, ord::numeric AS ord FROM jsonb_array_elements(st.features) WITH ORDINALITY AS t(f, ord)
      UNION ALL SELECT '"watch_order"'::jsonb, COALESCE((SELECT ord FROM jsonb_array_elements(st.features) WITH ORDINALITY AS t(f, ord) WHERE f = '"books"'::jsonb), 1000) + 0.5
    ) x)
  FROM public.universes u WHERE u.id = st.universe_id AND u.slug = 'harry-potter' AND NOT st.features ? 'watch_order';
