-- Cover photos (staff can replace them; only set while missing).
UPDATE public.universe_settings st SET theme = st.theme || jsonb_build_object('coverImage', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hogwarts_model_studio_tour.jpg?width=1600', 'coverCredit', 'Foto: Karen Roe · CC BY 2.0 · Wikimedia Commons') FROM public.universes u WHERE u.id = st.universe_id AND u.slug = 'harry-potter' AND NOT st.theme ? 'coverImage';
